import json
with open('/app/resources/treasury_bulletin_2010_03.json', 'r') as f:
    data = json.load(f)

# Print all top-level keys
print("Top-level keys:", list(data.keys())[:20])

# Search for tables
def find_tables(d, path=""):
    results = []
    if isinstance(d, dict):
        for k, v in d.items():
            new_path = f"{path}.{k}" if path else k
            if 'table' in str(k).lower():
                results.append((new_path, str(v)[:100]))
            results.extend(find_tables(v, new_path))
    elif isinstance(d, list):
        for i, item in enumerate(d[:10]):
            results.extend(find_tables(item, f"{path}[{i}]"))
    return results

tables = find_tables(data)
for t in tables[:10]:
    print(t)
