import json
with open('/app/resources/treasury_bulletin_2010_03.json', 'r') as f:
    data = json.load(f)

# Search the entire JSON for any 2004 data related to exchange rates
def search_all(obj, path="root", target_year="2004"):
    if isinstance(obj, str):
        if target_year in obj:
            print(f"Found '{target_year}' in {path}: {obj[:200]}")
        return
    if isinstance(obj, dict):
        for k, v in obj.items():
            search_all(v, f"{path}.{k}", target_year)
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search_all(item, f"{path}[{i}]", target_year)

search_all(data)
